function onLoad()
    createSetupButtons()
end

function createSetupButtons()
    self.createButton({
        label="Show Map Buttons", click_function="addButtons", function_owner=self,
        position={0.3,0.1,0}, rotation={0,90,0}, height=200, width=900,
        font_size=100, color={0,0,0}, font_color={1,1,1}
    })
    self.createButton({
        label="Hide Map Buttons", click_function="removeButtons", function_owner=self,
        position={-0.3,0.1,0}, rotation={0,90,0}, height=200, width=900,
        font_size=100, color={0,0,0}, font_color={1,1,1}
    })
end



function addButtons()

    --Button Bag
    MapButtonBag = getObjectFromGUID("6beabc")

    MapButtonBag.call("buttonClick_place")


end

function removeButtons()

    --Button Bag

    MapButtonBag = getObjectFromGUID("6beabc")

    MapButtonBag.call("buttonClick_recall")

end

function onLoad()
    createButtons()
end
function createButtons()
    if self.getDescription() == "white" then
        self.createButton({
            label="Get", click_function="draw_cube", function_owner=self,
            position={0, 0.50, 0}, rotation={0,90,0}, height=425, width=425,
            font_size=150, color=Color.fromString(self.getDescription()), font_color={0,0,0}
        })
    else
        self.createButton({
            label="Get", click_function="draw_cube", function_owner=self,
            position={0, 0.50, 0}, rotation={0,90,0}, height=425, width=425,
            font_size=150, color=Color.fromString(self.getDescription()), font_color={1,1,1}
        })
    end
end    

function draw_cube(obj, player_color)
    local player_color = self.getGMNotes()
    orientationList = Global.getTable("orientationValue")
    rr = orientationList[player_color]
    if not rr then return end

    --take_cube(self.getName(), self.getDescription(), 1, player_color, rr) 
    local params = {
        type = self.getName(),
        color = self.getDescription(),
        amount = 1,
        player_color = player_color,
        rota_value = rr,
    }
    Global.call("take_cube",params)
end

