function dice_roll(obj, player_color)
    local type = self.getGMNotes()
    local pDice = Global.getTable("playerDice")
    local cDice = pDice[self.getDescription()]
    if cDice ~= nil then
        self.clearButtons()
        local Die1 = getObjectFromGUID(cDice[self.getGMNotes().."1"])
        if Die1 ~= nil then            
            Die1.roll()        
            --if type == "C" then type = "C1" end
            Wait.time(function() die_results(self.getDescription(), type, Die1.guid) end, 2)
            Wait.time(function() return_die(self.getDescription(), Die1.getGMNotes(),Die1.guid) end, 3)
        end
        local Die2 = getObjectFromGUID(cDice[self.getGMNotes().."2"])
        if Die2 ~= nil then  
            Die2.roll()
            --if type == "C" then type = "C2" end
            Wait.time(function() die_results(self.getDescription(), type, Die2.guid) end, 2)
            Wait.time(function() return_die(self.getDescription(), Die2.getGMNotes(),Die2.guid) end, 3)
        end  
        Wait.time(function() createSetupButtons() end, 4)
    end
end    

