function createSetupButtons()
    if self.memo ~= "1" then
        self.createButton({
            label="2", click_function="setupMerchants", function_owner=self,
            position={-0.75, 0.1, -0.75}, rotation={0,0,0}, height=230, width=230,
            font_size=200, color={1,1,1}, font_color={0,0,0}
        })
    else
        local _Dice = Global.getTable("summonDice")
        local _NativesDie = getObjectFromGUID(_Dice["NativesDie"])
        local _AltNativesDie = getObjectFromGUID(_Dice["AltNativesDie"])
        if _NativesDie or _AltNativesDie then
            self.createButton({
                label="N", click_function="summonNatives", function_owner=self,
                position={0.75, 0.1, 0.75}, rotation={0,0,0}, height=230, width=230,
                font_size=200, color={1,1,1}, font_color={0,0,0}
            })
        end
    end
end

function setupMerchants()

    params = { guid = self.guid }
    Global.call("draw_merchants",params)

    self.memo = "1"
    self.clearButtons()
    createSetupButtons()

end

function summonNatives()

    params = { guid = self.guid }
    Global.call("summonLocation",params)

end
